-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.admin_remove_invites(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.require_admin_session();
  if jsonb_typeof(p) is distinct from 'object' then
    raise exception 'admin_remove_invites: expected { "emails": [...] } or { "list": "…" }' using errcode = '22023';
  end if;
  -- Only these two keys go through: "include_admins" (or anything else) is dropped.
  return public.remove_invites(
    (case when p ? 'emails' then jsonb_build_object('emails', p -> 'emails') else '{}'::jsonb end)
    || (case when p ? 'list' then jsonb_build_object('list', p -> 'list') else '{}'::jsonb end));
end;
$function$;

grant execute on function public.admin_remove_invites(p jsonb) to authenticated;
grant execute on function public.admin_remove_invites(p jsonb) to service_role;
